def minority_color(grid, exclude=()):
    """The least frequent color in the grid, ignoring the excluded ones (ties: lowest value)."""
    colors=[x for row in grid for x in row if x not in exclude]
    return min(sorted(set(colors)),key=colors.count)

def majority_color(grid, exclude=()):
    """The most frequent color in the grid, ignoring the excluded ones (ties: lowest value)."""
    colors=[x for row in grid for x in row if x not in exclude]
    return max(sorted(set(colors)),key=colors.count)

def bands(grid, axis, sep):
    """The index runs along axis 0 (rows) or 1 (cols) between full separator lines, as lists of indices."""
